def give_walk_in_payments_a_receipt_link(apps, schema_editor):
    """Desk payments recorded before receipts existed get their link too, so
    their receipts can be issued and sent like new ones."""
    PaymentHistory = apps.get_model('main', 'PaymentHistory')
    for payment in PaymentHistory.objects.filter(onsite_attendee__isnull=False, receipt_token__isnull=True):
        payment.receipt_token = secrets.token_urlsafe(32)
        payment.save(update_fields=['receipt_token'])


